package com.suks.sittiporn.lslamic.forgetpassword.forgetemail;import androidx.appcompat.app.AppCompatActivity;import android.os.Bundle;import com.suks.sittiporn.lslamic.R;public class ForgetEmailActivity extends AppCompatActivity {    @Override    protected void onCreate(Bundle savedInstanceState) {        super.onCreate(savedInstanceState);        setContentView(R.layout.forget_email_activity);        if (savedInstanceState == null) {            getSupportFragmentManager().beginTransaction()                    .replace(R.id.container, ForgetEmailFragment.newInstance())                    .commitNow();        }    }}